def generate_extended_data():
    """Generate extended social good training data."""
    output_tr = "data/training_sets/social_good_extended_tr.jsonl"
    output_en = "data/training_sets/social_good_extended_en.jsonl"

    # Write Turkish
    with open(output_tr, "w", encoding="utf-8") as f:
        for sample in TR_SAMPLES:
            entry = {
                "messages": [
                    {"role": "system", "content": SYSTEM_TR},
                    {"role": "user", "content": sample["user"]},
                    {"role": "assistant", "content": sample["assistant"]},
                ]
            }
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    print(f"[OK] TR extended data: {len(TR_SAMPLES)} samples → {output_tr}")

    # Write English
    with open(output_en, "w", encoding="utf-8") as f:
        for sample in EN_SAMPLES:
            entry = {
                "messages": [
                    {"role": "system", "content": SYSTEM_EN},
                    {"role": "user", "content": sample["user"]},
                    {"role": "assistant", "content": sample["assistant"]},
                ]
            }
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    print(f"[OK] EN extended data: {len(EN_SAMPLES)} samples → {output_en}")

    # Merge all data (original + extended)
    merged = "data/training_sets/social_good_all.jsonl"
    all_lines = []

    for path in [
        "data/training_sets/social_good_base_tr.jsonl",
        "data/training_sets/social_good_base_en.jsonl",
        output_tr,
        output_en,
    ]:
        try:
            with open(path, "r", encoding="utf-8") as f:
                for line in f:
                    if line.strip():
                        all_lines.append(line.strip())
        except FileNotFoundError:
            print(f"[WARN] {path} not found, skipping")

    random.seed(42)
    random.shuffle(all_lines)

    with open(merged, "w", encoding="utf-8") as f:
        for line in all_lines:
            f.write(line + "\n")

    print(f"[OK] Merged dataset: {len(all_lines)} total samples → {merged}")
    return merged, len(all_lines)


if __name__ == "__main__":
    merged, count = generate_extended_data()
    print(f"\nTotal: {count} training samples ready for 2-hour training session.")
